30	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
31	      invoices: [{ id: 1, projectId: 1, amount: 120, status: 'SENT' }],
32	    });
33	
34	    await page.goto('/projects');
35	    await page.getByTestId('project-open-1').click();
36	
37	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
38	
39	    const row = page.getByTestId('invoice-row-1');
40	    await expect(row).toBeVisible();
41	    // The invoice surfaces a status, and a control to mark it paid.
42	    await expect(row.getByTestId('invoice-status')).toBeVisible();
43	    await expect(page.getByTestId('invoice-pay-1')).toBeVisible();
44	
45	    // reset cleared the audit file — nothing has been marked paid yet.
46	    expect(auditLines()).toEqual([]);
47	
48	    await page.getByTestId('invoice-pay-1').click();
49	
50	    // The invoice's status reflects that it is now paid.
51	    await expect(row.getByTestId('invoice-status')).toHaveText(/^paid$/i);
52	
53	    // And exactly one record was kept for the action, naming the invoice and its amount.
54	    await expect
55	      .poll(() => auditLines().filter((l) => /^INVOICE_PAID id=1 amount=120(\.0+)?$/.test(l)))
